fn may_have_animations(&self) -> bool {
    if let Some(pseudo) = self.implemented_pseudo_element()
        && pseudo.animations_stored_in_parent()
    {
        // FIXME(emilio): When would the parent of a ::before / ::after
        // pseudo-element be null?
        return self.parent_element().is_some_and(|p| {
            p.as_node()
                .get_bool_flag(nsINode_BooleanFlag::ElementHasAnimations)
        });
    }
    self.as_node()
        .get_bool_flag(nsINode_BooleanFlag::ElementHasAnimations)
}

bool Gecko_ElementHasAnimations(const Element* aElement) {
  const auto [element, pseudo] = AnimationUtils::GetElementPseudoPair(aElement);
  return !!EffectSet::Get(element, pseudo);
}

void KeyframeEffect::UpdateTargetRegistration() {
  if (!mTarget) {
    return;
  }

  bool isRelevant = mAnimation && mAnimation->IsRelevant();

  // Animation::IsRelevant() returns a cached value. It only updates when
  // something calls Animation::UpdateRelevance. Whenever our timing changes,
  // we should be notifying our Animation before calling this, so
  // Animation::IsRelevant() should be up-to-date by the time we get here.
  MOZ_ASSERT(isRelevant ==
                 ((IsCurrent() || IsInEffect()) && mAnimation &&
                  mAnimation->ReplaceState() != AnimationReplaceState::Removed),
             "Out of date Animation::IsRelevant value");

  if (isRelevant && !mInEffectSet) {
    EffectSet* effectSet = EffectSet::GetOrCreate(mTarget);
    effectSet->AddEffect(*this);
    mInEffectSet = true;
    UpdateEffectSet(effectSet);
    nsIFrame* frame = GetPrimaryFrame();
    EnumerateContinuationsOrIBSplitSiblings(
        frame, [](nsIFrame* aFrame) { aFrame->MarkNeedsDisplayItemRebuild(); });
  } else if (!isRelevant && mInEffectSet) {
    UnregisterTarget();
  }
}

void KeyframeEffect::UnregisterTarget() {
  if (!mInEffectSet) {
    return;
  }

  EffectSet* effectSet = EffectSet::Get(mTarget);
  MOZ_ASSERT(effectSet,
             "If mInEffectSet is true, there must be an EffectSet"
             " on the target element");
  mInEffectSet = false;
  if (effectSet) {
    effectSet->RemoveEffect(*this);

    if (effectSet->IsEmpty()) {
      EffectSet::DestroyEffectSet(mTarget);
    }
  }
  nsIFrame* frame = GetPrimaryFrame();
  EnumerateContinuationsOrIBSplitSiblings(
      frame, [](nsIFrame* aFrame) { aFrame->MarkNeedsDisplayItemRebuild(); });
}

pub fn propagate(&mut self, traversal_flags: &TraversalFlags) -> Self {
    // In the middle of an animation only restyle, we don't need to
    // propagate any restyle hints, and we need to remove ourselves.
    if traversal_flags.for_animation_only() {
        self.remove_animation_hints();
        return Self::empty();
    }

    debug_assert!(
        !self.has_animation_hint(),
        "There should not be any animation restyle hints \
         during normal traversal"
    );

    // Else we should clear ourselves, and return the propagated hint.
    std::mem::take(self).propagate_for_non_animation_restyle()
}

pub fn remove_animation_hints(&mut self) {
    self.remove(Self::for_animations());

    // While RECASCADE_SELF is not animation-specific, we only ever add and process it during
    // traversal.  If we are here, removing animation hints, then we are in an animation-only
    // traversal, and we know that any RECASCADE_SELF flag must have been set due to changes in
    // inherited values after restyling for animations, and thus we want to remove it so that
    // we don't later try to restyle the element during a normal restyle.
    // (We could have separate RECASCADE_SELF_NORMAL and RECASCADE_SELF_ANIMATIONS flags to
    // make it clear, but this isn't currently necessary.)
    self.remove(Self::RECASCADE_SELF | Self::RECASCADE_SELF_IF_INHERIT_RESET_STYLE);
}
